struct ActorProfile {
  std::string_view guest_sha256;
  uint32_t info_table,base_offset;
  std::span<const ActorRoutineProof> routines;
  std::string_view base_identity_evidence,actor_value_index_evidence;
};
inline constexpr std::array<ActorProfile,2> kActorProfiles{{
  {kJulyActorGuestSha256,kJulyActorInfoTable,kJulyActorBaseOffset,kJulyActorRoutines,
   "validated-july-handler-base-access-and-TESNPC-RTTI","validated-july-script-name-table"},
  {"1e91b9b9fb9f9602005f4c03f47e95f437bfe81883b6ce1072f8f7c68d892736",0x83180FF0,0x30,k2011ActorRoutines,
   "validated-2011-handler-base-access-and-TESNPC-RTTI","validated-2011-script-name-table"}
}};
inline const ActorProfile* FindActorProfile(std::string_view sha256) {
  for(const auto& profile:kActorProfiles) if(profile.guest_sha256==sha256) return &profile;
  return nullptr;
}
